1	import fs from 'node:fs';
2	import fsp from 'node:fs/promises';
3	import path from 'node:path';
4	import * as store from './sessions.js';
5	import { WORKSPACES_DIR } from './config.js';
6	
7	// Workspace-wide trace analytics: parse every Claude transcript and Codex
8	// rollout on the Space into per-conversation stats (turns, tool calls, web
9	// searches, tokens), attribute them to Agent Manager sessions where possible
10	// (Claude: transcript filename == sessionUuid; Codex: pinned codexSessionId),
11	// and aggregate the rest as "other".
12	//
13	// Parsing is memoized per file by (mtime, size), so repeat calls only re-read
14	// files that actually changed — important on the bucket mount.
15	
16	const fileCache = new Map(); // path -> { key, parsed: { stats, digest } }
17	// Parsing is synchronous CPU; between files we hand the event loop back so a
18	// cold build (boot warmup after a rebuild) doesn't freeze every request for
19	// minutes. Worst blocking stretch becomes one file (~1s), not the whole scan.
20	const yieldLoop = () => new Promise((r) => setImmediate(r));
21	let resultMemo = { ts: 0, val: null };
22	const TTL = 400; // Overview polls at ~1Hz; per-file mtime caching keeps re-scans cheap
23	
24	function emptyStats() {
25	  return { turns: 0, prompts: 0, toolCalls: 0, tools: {}, web: 0, tokensIn: 0, tokensOut: 0, cacheRead: 0, firstTs: 0, lastTs: 0, files: 0 };
26	}
27	
28	function addTs(st, iso) {
29	  const t = Date.parse(iso);
30	  if (!t) return;
31	  if (!st.firstTs || t < st.firstTs) st.firstTs = t;
32	  if (t > st.lastTs) st.lastTs = t;
33	}
34	
35	function mergeInto(a, b) {
36	  a.turns += b.turns; a.prompts += b.prompts; a.toolCalls += b.toolCalls; a.web += b.web;
37	  a.tokensIn += b.tokensIn; a.tokensOut += b.tokensOut; a.cacheRead += b.cacheRead; a.files += b.files;
38	  for (const [k, v] of Object.entries(b.tools)) a.tools[k] = (a.tools[k] || 0) + v;
39	  if (b.firstTs && (!a.firstTs || b.firstTs < a.firstTs)) a.firstTs = b.firstTs;
40	  if (b.lastTs > a.lastTs) a.lastTs = b.lastTs;
41	}
42	
43	// ---------- "since your last prompt" digest (for the Overview cards) ----------
44	// Built in the same parse pass: every real user prompt resets the segment, so
45	// whatever accumulated by EOF is the activity since the last thing you said.
46	function emptyDigest() {
47	  return { lastPromptText: '', lastPromptRaw: '', lastPromptTs: 0, lastAssistantText: '', lastAssistantMd: '', lastAssistantTs: 0, sinceTurns: 0, sinceToolCalls: 0, sinceTools: {}, sinceFiles: [], sinceTokens: 0, running: false, turnsLog: [] };
48	}
49	const clip = (s, n = 280) => { const t = (s || '').replace(/\s+/g, ' ').trim(); return t.length > n ? `${t.slice(0, n - 1)}…` : t; };
50	// Markdown-preserving variant (keeps newlines) for the expandable card view.
51	const clipRaw = (s, n = 6000) => { const t = (s || '').trim(); return t.length > n ? `${t.slice(0, n - 1)}…` : t; };
52	// turnsLog: the model's intermediate turns WITHIN the current request (newest
53	// first) so the Overview can page through them. Each new assistant text pushes
54	// the previous one into the log; a new user prompt clears it.
55	const MAX_TURNS_LOG = 24;
56	function digestPrompt(d, text, ts) {
57	  d.lastPromptText = clip(text); d.lastPromptRaw = clipRaw(text); d.lastPromptTs = Date.parse(ts) || 0;
58	  d.sinceTurns = 0; d.sinceToolCalls = 0; d.sinceTools = {}; d.sinceFiles = []; d.sinceTokens = 0;
59	  d.turnsLog = []; // arrows only walk the current request's turns
60	  // The previous answer belongs to the previous prompt — never show it as "LAST".
61	  d.lastAssistantText = ''; d.lastAssistantMd = ''; d.lastAssistantTs = 0;
62	}
63	function digestAssistant(d, text, ts) {
64	  const clipped = clip(text);
65	  // Same text again (codex mirrors agent_message/response_item/task_complete):
66	  // refresh metadata only, don't log a phantom turn.
67	  if (clipped !== d.lastAssistantText) {
68	    if (d.lastAssistantText) {
69	      d.turnsLog.unshift({ answer: d.lastAssistantText, answerMd: d.lastAssistantMd, ts: d.lastAssistantTs });
70	      if (d.turnsLog.length > MAX_TURNS_LOG) d.turnsLog.pop();
71	    }
72	    d.lastAssistantText = clipped;
73	  }
74	  d.lastAssistantMd = clipRaw(text);
75	  d.lastAssistantTs = Date.parse(ts) || d.lastAssistantTs;
76	}
77	function digestTool(d, name, file) {
78	  d.sinceToolCalls++;
79	  d.sinceTools[name] = (d.sinceTools[name] || 0) + 1;
80	  if (file && !d.sinceFiles.includes(file) && d.sinceFiles.length < 12) d.sinceFiles.push(file);
81	}
82	
83	// ---------- Claude transcripts (CLAUDE_CONFIG_DIR/projects/**/<uuid>.jsonl) ----------
84	// Multi-block assistant messages repeat the same message.id AND usage across
85	// several lines — dedupe both turns/usage (by message id) and tool_use blocks
86	// (by block id) or everything double-counts.
87	function parseClaude(txt) {
88	  const st = emptyStats();
89	  const dg = emptyDigest();
90	  st.files = 1;
91	  const seenMsg = new Set();
92	  const seenTool = new Set();
93	  for (const line of txt.split('\n')) {
94	    if (!line) continue;
95	    let j; try { j = JSON.parse(line); } catch { continue; }
96	    if (j.timestamp) addTs(st, j.timestamp);
97	    if (j.type === 'assistant' && j.message) {
98	      const m = j.message;
99	      const id = m.id || `${j.uuid || Math.random()}`;
100	      if (!seenMsg.has(id)) {
101	        seenMsg.add(id);
102	        st.turns++;
103	        dg.sinceTurns++;
104	        const u = m.usage;
105	        if (u) {
106	          st.tokensIn += (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0);
107	          st.cacheRead += u.cache_read_input_tokens || 0;
108	          st.tokensOut += u.output_tokens || 0;
109	          dg.sinceTokens += (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.output_tokens || 0);
110	          const w = u.server_tool_use;
111	          if (w) st.web += (w.web_search_requests || 0) + (w.web_fetch_requests || 0);
112	        }
113	      }
114	      if (Array.isArray(m.content)) {
115	        for (const c of m.content) {
116	          if (!c) continue;
117	          if (c.type === 'tool_use' && !seenTool.has(c.id)) {
118	            seenTool.add(c.id);
119	            st.toolCalls++;
120	            const name = c.name || 'tool';
121	            st.tools[name] = (st.tools[name] || 0) + 1;
122	            if (/^web(search|fetch)$/i.test(name)) st.web++;
123	            const file = /^(Edit|Write|MultiEdit|NotebookEdit)$/.test(name) && c.input && c.input.file_path;
124	            digestTool(dg, name, file || null);
125	          } else if (c.type === 'text' && c.text && c.text.trim()) {
126	            digestAssistant(dg, c.text, j.timestamp);
127	          }
128	        }
129	      }
130	    } else if (j.type === 'user' && !j.toolUseResult && !j.isMeta && !j.sourceToolUseID) {
131	      // isMeta/sourceToolUseID mark harness-injected "user" lines (skill
132	      // payloads, attached context) — not something the operator typed.
133	      st.prompts++;
134	      const mc = j.message && j.message.content;
135	      const text = typeof mc === 'string' ? mc
136	        : Array.isArray(mc) ? mc.filter((c) => c && c.type === 'text').map((c) => c.text).join(' ') : '';
137	      // Skip harness noise (slash-command wrappers, attachments, interrupt
138	      // markers) as "prompts".
139	      const t = text.trim();
140	      if (t && !t.startsWith('<') && !t.startsWith('[Request interrupted')) digestPrompt(dg, text, j.timestamp);
141	    }
142	  }
143	  return { stats: st, digest: dg };
144	}
145	
146	// ---------- Codex rollouts (CODEX_HOME/sessions/**/rollout-*-<uuid>.jsonl) ----------
147	const codexText = (p) => (Array.isArray(p.content) ? p.content.map((c) => (c && c.text) || '').join(' ') : '');
148	
149	function parseCodex(txt) {
150	  const st = emptyStats();
151	  const dg = emptyDigest();
152	  st.files = 1;
153	  let tok = null; // token_count events are cumulative per run — keep the last
154	  let tokAtPrompt = 0; // cumulative total when you last prompted (for sinceTokens)
155	  for (const line of txt.split('\n')) {
156	    if (!line) continue;
157	    let j; try { j = JSON.parse(line); } catch { continue; }
158	    if (j.timestamp) addTs(st, j.timestamp);
159	    const p = j.payload || {};
160	    if (j.type === 'session_meta') {
161	      if (p.cwd) st.cwd = p.cwd; // for cwd-fallback attribution
162	      // Codex >=0.142 spawns internal "guardian" safety-judge subagents whose
163	      // rollouts share the session's cwd. They aren't the user's conversation —
164	      // flag them so build() skips attribution (they'd otherwise pollute or
165	      // blank out the Overview digest).
166	      if (p.thread_source === 'subagent' || (p.source && p.source.subagent)) st.subagent = true;
167	    }
168	    if (j.type === 'response_item') {
169	      switch (p.type) {
170	        case 'message':
171	          if (p.role === 'assistant') {
172	            st.turns++;
173	            dg.sinceTurns++;
174	            const t = codexText(p);
175	            if (t.trim()) digestAssistant(dg, t, j.timestamp);
176	          } else if (p.role === 'user') {
177	            st.prompts++;
178	            const t = codexText(p);
179	            // Codex wraps environment/instructions as user items — skip those.
180	            if (t.trim() && !t.trim().startsWith('<')) {
181	              digestPrompt(dg, t, j.timestamp);
182	              tokAtPrompt = tok ? (tok.total_tokens || 0) : 0;
183	            }
184	          }
185	          break;
186	        case 'function_call':
187	        case 'custom_tool_call':
188	        case 'local_shell_call': {
189	          st.toolCalls++;
190	          const name = p.name || p.type;
191	          st.tools[name] = (st.tools[name] || 0) + 1;
192	          // apply_patch arguments carry the touched files in the patch header
193	          let file = null;
194	          if (name === 'apply_patch' && typeof p.arguments === 'string') {
195	            const m = p.arguments.match(/\*\*\* (?:Update|Add|Delete) File: ([^\\\n"]+)/);
196	            if (m) file = m[1].trim();
197	          }
198	          digestTool(dg, name, file);
199	          break;
200	        }
201	        case 'web_search_call':
202	          st.web++;
203	          st.toolCalls++;
204	          st.tools.web_search = (st.tools.web_search || 0) + 1;
205	          digestTool(dg, 'web_search', null);
206	          break;
207	        default:
208	      }
209	    } else if (j.type === 'event_msg') {
210	      // Task lifecycle: Codex runs one task per user prompt, made of several
211	      // model turns. task_started/task_complete bracket it — that (not "an
212	      // assistant message appeared") is the real running/done signal, and
213	      // task_complete carries the authoritative final answer.
214	      switch (p.type) {
215	        case 'token_count':
216	          if (p.info && p.info.total_token_usage) tok = p.info.total_token_usage;
217	          break;
218	        case 'task_started':
219	          dg.running = true;
220	          break;
221	        case 'agent_message':
222	          if (p.message) digestAssistant(dg, p.message, j.timestamp); // live progress text
223	          break;
224	        case 'task_complete':
225	          dg.running = false;
226	          if (p.last_agent_message) digestAssistant(dg, p.last_agent_message, j.timestamp);
227	          break;
228	        default:
229	      }
230	    }
231	  }
232	  if (tok) {
233	    const cached = tok.cached_input_tokens || 0;
234	    st.tokensIn = Math.max(0, (tok.input_tokens || 0) - cached); // align with Claude: fresh input only
235	    st.cacheRead = cached;
236	    st.tokensOut = tok.output_tokens || 0;
237	    dg.sinceTokens = Math.max(0, (tok.total_tokens || 0) - tokAtPrompt);
238	  }
239	  return { stats: st, digest: dg };
240	}
241	
242	// ---------- OpenClaw sessions (~/.openclaw/agents/*/sessions/<uuid>.jsonl) ----------
243	// Line shape: { type: 'message', timestamp, message: { role, content: [{type:'text',text}],
244	// usage: { input, output, cacheRead, ... } } } — other line types are metadata.
245	const ocText = (m) => Array.isArray(m.content)
246	  ? m.content.filter((c) => c && c.type === 'text' && c.text).map((c) => c.text).join(' ')
247	  : (typeof m.content === 'string' ? m.content : '');
248	
249	function parseOpenClaw(txt) {
250	  const st = emptyStats();
251	  const dg = emptyDigest();
252	  st.files = 1;
253	  for (const line of txt.split('\n')) {
254	    if (!line) continue;
255	    let j; try { j = JSON.parse(line); } catch { continue; }
256	    if (j.timestamp) addTs(st, j.timestamp);
257	    if (j.type !== 'message' || !j.message) continue;
258	    const m = j.message;
259	    const text = ocText(m);
260	    if (m.role === 'user') {
261	      st.prompts++;
262	      if (text.trim() && !text.trim().startsWith('<')) digestPrompt(dg, text, j.timestamp);
263	    } else if (m.role === 'assistant') {
264	      st.turns++;
265	      dg.sinceTurns++;
266	      if (text.trim()) digestAssistant(dg, text, j.timestamp);
267	      const u = m.usage;
268	      if (u) {
269	        const cached = u.cacheRead || 0;
270	        st.tokensIn += Math.max(0, (u.input || 0) - cached);
271	        st.cacheRead += cached;
272	        st.tokensOut += u.output || 0;
273	        dg.sinceTokens += (u.input || 0) + (u.output || 0);
274	      }
275	      if (Array.isArray(m.content)) {
276	        for (const cb of m.content) {
277	          if (cb && typeof cb.type === 'string' && /tool/i.test(cb.type)) {
278	            st.toolCalls++;
279	            const name = cb.name || cb.toolName || 'tool';
280	            st.tools[name] = (st.tools[name] || 0) + 1;
281	            digestTool(dg, name, null);
282	          }
283	        }
284	      }
285	    }
286	  }
287	  return { stats: st, digest: dg };
288	}
289	
290	function openclawFiles() {
291	  return memoList('openclaw', openclawFilesUncached);
292	}
293	async function openclawFilesUncached() {
294	  const root = path.join(process.env.OPENCLAW_STATE_DIR || path.join(process.env.HOME || '', '.openclaw'), 'agents');
295	  const out = [];
296	  let agents = [];
297	  try { agents = await fsp.readdir(root, { withFileTypes: true }); } catch { return out; }
298	  for (const a of agents) {
299	    if (!a.isDirectory()) continue;
300	    const dir = path.join(root, a.name, 'sessions');
301	    let files = [];
302	    try { files = await fsp.readdir(dir); } catch { continue; }
303	    for (const f of files) {
304	      if (f.endsWith('.jsonl') && !f.includes('.trajectory')) out.push(path.join(dir, f));
305	    }
306	  }
307	  return out;
308	}
309	
310	// ---------- opencode (SQLite: ~/.local/share/opencode/opencode.db) ----------
311	// v1.x keeps conversations in SQLite (session/message/part with JSON payloads).
312	// Read-only via node:sqlite (node >= 22.5; degrades to "no digest" elsewhere).
313	let DatabaseSync = null;
314	try { ({ DatabaseSync } = await import('node:sqlite')); } catch { /* older node: skip opencode */ }
315	
316	function opencodeDbPath() {
317	  const xdgData = process.env.XDG_DATA_HOME || path.join(process.env.HOME || '', '.local', 'share');
318	  return path.join(xdgData, 'opencode', 'opencode.db');
319	}
320	
321	// WAL mode appends to <db>-wal without touching the main file's mtime — the
322	// change key and the hot-file check must look at both.
323	function dbChangeKey(p) {
324	  let m;
325	  try { m = fs.statSync(p); } catch { return null; }
326	  let w = null;
327	  try { w = fs.statSync(`${p}-wal`); } catch {}
328	  return {
329	    key: `${m.mtimeMs}:${m.size}:${w?.mtimeMs || 0}:${w?.size || 0}`,
330	    hotMs: Math.max(m.mtimeMs, w?.mtimeMs || 0),
331	  };
332	}
333	
334	let ocMemo = { key: '', rows: [] };
335	
336	function readOpencode() {
337	  if (!DatabaseSync) return [];
338	  const p = opencodeDbPath();
339	  const ck = dbChangeKey(p);
340	  if (!ck) return [];
341	  if (ocMemo.key === ck.key) return ocMemo.rows;
342	  // actively written db on the FUSE mount: serve the previous read (first read allowed)
343	  if (ocMemo.key && Date.now() - ck.hotMs < 8_000) return ocMemo.rows;
344	  const key = ck.key;
345	  let db;
346	  try { db = new DatabaseSync(p, { readOnly: true }); } catch { return ocMemo.rows; }
347	  const rows = [];
348	  try {
349	    const sessions = db.prepare('select * from session').all();
350	    const qLastUser = db.prepare("select id, time_created from message where session_id = ? and json_extract(data,'$.role') = 'user' order by time_created desc limit 1");
351	    const qPromptText = db.prepare("select json_extract(data,'$.text') t from part where message_id = ? and json_extract(data,'$.type') = 'text' order by time_created");
352	    const qCount = db.prepare("select count(*) c from message where session_id = ? and time_created > ? and json_extract(data,'$.role') = ?");
353	    const qTools = db.prepare("select json_extract(data,'$.tool') tool, count(*) c from part where session_id = ? and time_created > ? and json_extract(data,'$.type') = 'tool' group by 1");
354	    const qSinceTok = db.prepare("select coalesce(sum(json_extract(data,'$.tokens.total')), 0) t from part where session_id = ? and time_created > ? and json_extract(data,'$.type') = 'step-finish'");
355	    const qLastAssistant = db.prepare("select json_extract(p.data,'$.text') t, p.time_created ts from part p join message m on m.id = p.message_id where p.session_id = ? and p.time_created > ? and json_extract(p.data,'$.type') = 'text' and json_extract(m.data,'$.role') = 'assistant' order by p.time_created desc limit 1");
356	    for (const s of sessions) {
357	      const st = emptyStats();
358	      const dg = emptyDigest();
359	      st.files = 1;
360	      st.cwd = s.directory || null;
361	      st.tokensIn = s.tokens_input || 0;
362	      st.tokensOut = s.tokens_output || 0;
363	      st.cacheRead = s.tokens_cache_read || 0;
364	      st.firstTs = Number(s.time_created) || 0;
365	      st.lastTs = Number(s.time_updated) || st.firstTs;
366	      st.prompts = qCount.get(s.id, 0, 'user').c;
367	      st.turns = qCount.get(s.id, 0, 'assistant').c;
368	      for (const t of qTools.all(s.id, 0)) {
369	        const name = t.tool || 'tool';
370	        st.tools[name] = (st.tools[name] || 0) + t.c;
371	        st.toolCalls += t.c;
372	        if (/web/i.test(name)) st.web += t.c;
373	      }
374	      const lastU = qLastUser.get(s.id);
375	      const t0 = lastU ? Number(lastU.time_created) || 0 : 0;
376	      if (lastU) {
377	        const text = qPromptText.all(lastU.id).map((r) => r.t).filter(Boolean).join(' ');
378	        if (text.trim() && !text.trim().startsWith('<')) {
379	          dg.lastPromptText = clip(text);
380	          dg.lastPromptRaw = clipRaw(text);
381	          dg.lastPromptTs = t0;
382	        }
383	        dg.sinceTurns = qCount.get(s.id, t0, 'assistant').c;
384	        for (const t of qTools.all(s.id, t0)) {
385	          const name = t.tool || 'tool';
386	          dg.sinceTools[name] = (dg.sinceTools[name] || 0) + t.c;
387	          dg.sinceToolCalls += t.c;
388	        }
389	        dg.sinceTokens = qSinceTok.get(s.id, t0).t || 0;
390	      }
391	      // Only an answer NEWER than the prompt counts — a stale one means "working".
392	      const lastA = qLastAssistant.get(s.id, t0);
393	      if (lastA && lastA.t) {
394	        dg.lastAssistantText = clip(lastA.t);
395	        dg.lastAssistantMd = clipRaw(lastA.t);
396	        dg.lastAssistantTs = Number(lastA.ts) || 0;
397	      }
398	      rows.push({ directory: s.directory || null, parsed: { stats: st, digest: dg } });
399	    }
400	  } catch { /* torn read / schema drift: keep previous */ } finally {
401	    try { db.close(); } catch {}
402	  }
403	  ocMemo = { key, rows };
404	  return rows;
405	}
