407	// ---------- Hermes (SQLite: ~/.hermes/state.db, WAL) ----------
408	// sessions carry cwd + token totals; messages carry role/content/tool_name.
409	// Timestamps are float SECONDS — converted to ms for digest fields.
410	let hermesMemo = { key: '', rows: [] };
411	
412	function readHermes() {
413	  if (!DatabaseSync) return [];
414	  const p = path.join(process.env.HOME || '', '.hermes', 'state.db');
415	  const ck = dbChangeKey(p);
416	  if (!ck) return [];
417	  if (hermesMemo.key === ck.key) return hermesMemo.rows;
418	  if (hermesMemo.key && Date.now() - ck.hotMs < 8_000) return hermesMemo.rows;
419	  let db;
420	  try { db = new DatabaseSync(p, { readOnly: true }); } catch { return hermesMemo.rows; }
421	  const rows = [];
422	  try {
423	    const sessions = db.prepare('select * from sessions').all();
424	    const qLastUser = db.prepare("select content, timestamp from messages where session_id = ? and role = 'user' and active = 1 order by timestamp desc limit 1");
425	    const qRole = db.prepare("select count(*) c from messages where session_id = ? and timestamp > ? and role = ?");
426	    const qTools = db.prepare("select tool_name, count(*) c from messages where session_id = ? and timestamp > ? and tool_name is not null group by 1");
427	    const qTok = db.prepare("select coalesce(sum(token_count), 0) t from messages where session_id = ? and timestamp > ?");
428	    const qLastAssistant = db.prepare("select content, timestamp from messages where session_id = ? and role = 'assistant' and content is not null and content != '' and timestamp > ? order by timestamp desc limit 1");
429	    const qMaxTs = db.prepare('select max(timestamp) t from messages where session_id = ?');
430	    for (const s of sessions) {
431	      const st = emptyStats();
432	      const dg = emptyDigest();
433	      st.files = 1;
434	      st.cwd = s.cwd || null;
435	      st.tokensIn = s.input_tokens || 0;
436	      st.tokensOut = s.output_tokens || 0;
437	      st.cacheRead = s.cache_read_tokens || 0;
438	      st.firstTs = Math.round((Number(s.started_at) || 0) * 1000);
439	      const maxTs = qMaxTs.get(s.id)?.t;
440	      st.lastTs = maxTs ? Math.round(Number(maxTs) * 1000) : st.firstTs;
441	      st.prompts = qRole.get(s.id, 0, 'user').c;
442	      st.turns = qRole.get(s.id, 0, 'assistant').c;
443	      for (const t of qTools.all(s.id, 0)) {
444	        const name = t.tool_name || 'tool';
445	        st.tools[name] = (st.tools[name] || 0) + t.c;
446	        st.toolCalls += t.c;
447	        if (/web|search/i.test(name)) st.web += t.c;
448	      }
449	      const lastU = qLastUser.get(s.id);
450	      const t0 = lastU ? Number(lastU.timestamp) || 0 : 0; // seconds, for queries
451	      if (lastU) {
452	        const text = String(lastU.content || '');
453	        if (text.trim() && !text.trim().startsWith('<')) {
454	          dg.lastPromptText = clip(text);
455	          dg.lastPromptRaw = clipRaw(text);
456	          dg.lastPromptTs = Math.round(t0 * 1000);
457	        }
458	        dg.sinceTurns = qRole.get(s.id, t0, 'assistant').c;
459	        for (const t of qTools.all(s.id, t0)) {
460	          const name = t.tool_name || 'tool';
461	          dg.sinceTools[name] = (dg.sinceTools[name] || 0) + t.c;
462	          dg.sinceToolCalls += t.c;
463	        }
464	        dg.sinceTokens = qTok.get(s.id, t0).t || 0;
465	      }
466	      const lastA = qLastAssistant.get(s.id, t0);
467	      if (lastA && lastA.content) {
468	        dg.lastAssistantText = clip(lastA.content);
469	        dg.lastAssistantMd = clipRaw(lastA.content);
470	        dg.lastAssistantTs = Math.round((Number(lastA.timestamp) || 0) * 1000);
471	      }
472	      rows.push({ directory: s.cwd || null, parsed: { stats: st, digest: dg } });
473	    }
474	  } catch { /* torn read / schema drift: keep previous */ } finally {
475	    try { db.close(); } catch {}
476	  }
477	  hermesMemo = { key: ck.key, rows };
478	  return rows;
479	}
480	
481	// Cap how much of a transcript we load. A long-running agent's .jsonl can grow
482	// to hundreds of MB; reading it whole (and splitting into a line array) can OOM
483	// the single process. Above the cap we read only the tail (dropping the partial
484	// first line), which keeps the "since your last prompt" digest accurate while
485	// bounding memory — older cumulative totals for that one file become approximate.
486	const MAX_TRACE_BYTES = 12 * 1024 * 1024;
487	async function readTraceFile(p, size) {
488	  if (size <= MAX_TRACE_BYTES) return fsp.readFile(p, 'utf8');
489	  const fh = await fsp.open(p, 'r');
490	  try {
491	    const buf = Buffer.alloc(MAX_TRACE_BYTES);
492	    await fh.read(buf, 0, MAX_TRACE_BYTES, size - MAX_TRACE_BYTES);
493	    const s = buf.toString('utf8');
494	    const nl = s.indexOf('\n');
495	    return nl >= 0 ? s.slice(nl + 1) : s;
496	  } finally { await fh.close(); }
497	}
498	
499	async function statsFor(p, parser, quietMs = 0) {
500	  const c = fileCache.get(p);
501	  const now = Date.now();
502	  // Dormant transcripts (untouched for a day) skip the stat entirely for a
503	  // minute at a time: hundreds of FUSE getattr round-trips per rebuild were
504	  // most of the Overview's first-open wait.
505	  if (c && c.statAt && now - c.statAt < 60_000 && c.mtimeMs && now - c.mtimeMs > 86_400_000) return c.parsed;
506	  let m;
507	  try { m = await fsp.stat(p); } catch { return null; }
508	  const key = `${m.mtimeMs}:${m.size}`;
509	  if (c && c.key === key) { c.statAt = now; c.mtimeMs = m.mtimeMs; return c.parsed; }
510	  // Don't read a file its owner is actively writing. OpenClaw's session fence
511	  // fingerprints metadata at nanosecond precision, and on the FUSE bucket our
512	  // reads can disturb what it sees — so while a fence-sensitive file is hot,
513	  // serve the previous parse and re-read once writes have gone quiet.
514	  if (quietMs && c && Date.now() - m.mtimeMs < quietMs) return c.parsed;
515	  // Parsing is synchronous CPU on THE event loop. A big transcript being
516	  // actively written changes every poll; re-parsing tens of MB once a second
517	  // starves every other request (blank app). Heavy files therefore re-parse
518	  // on a duty cycle: at most ~10% of wall time, capped at one parse per 10s.
519	  if (c && c.cost > 150 && Date.now() - c.at < Math.min(10_000, c.cost * 10)) return c.parsed;
520	  let parsed;
521	  const t0 = Date.now();
522	  try { parsed = parser(await readTraceFile(p, m.size)); } catch { return null; }
523	  fileCache.set(p, { key, parsed, cost: Date.now() - t0, at: t0, statAt: now, mtimeMs: m.mtimeMs });
524	  return parsed;
525	}
526	
527	// Directory walks (readdir over FUSE) also add up when repeated per rebuild —
528	// remember each file list briefly. New transcript files appear within 5s.
529	const listMemo = new Map(); // key -> { ts, val: Promise<string[]> }
530	function memoList(key, fn) {
531	  const c = listMemo.get(key);
532	  if (c && Date.now() - c.ts < 5_000) return c.val;
533	  const val = fn();
534	  listMemo.set(key, { ts: Date.now(), val });
535	  return val;
536	}
537	
538	function claudeFiles() {
539	  return memoList('claude', claudeFilesUncached);
540	}
541	async function claudeFilesUncached() {
542	  const home = process.env.HOME || '';
543	  const dirs = [process.env.CLAUDE_CONFIG_DIR, path.join(home, '.claude'), path.join(home, '.config', 'claude')]
544	    .filter(Boolean).filter((d, i, a) => a.indexOf(d) === i);
545	  const out = [];
546	  for (const d of dirs) {
547	    const proj = path.join(d, 'projects');
548	    let projects = [];
549	    try { projects = await fsp.readdir(proj, { withFileTypes: true }); } catch { continue; }
550	    for (const e of projects) {
551	      if (!e.isDirectory()) continue;
552	      let files = [];
553	      try { files = await fsp.readdir(path.join(proj, e.name)); } catch { continue; }
554	      for (const f of files) if (f.endsWith('.jsonl')) out.push(path.join(proj, e.name, f));
555	    }
556	  }
557	  return out;
558	}
559	
560	function codexFiles() {
561	  return memoList('codex', codexFilesUncached);
562	}
563	async function codexFilesUncached() {
564	  const home = process.env.CODEX_HOME || path.join(process.env.HOME || '', '.codex');
565	  const root = path.join(home, 'sessions');
566	  const out = [];
567	  const walk = async (dir, depth) => {
568	    if (depth > 5) return;
569	    let ents = [];
570	    try { ents = await fsp.readdir(dir, { withFileTypes: true }); } catch { return; }
571	    for (const e of ents) {
572	      const p = path.join(dir, e.name);
573	      if (e.isDirectory()) await walk(p, depth + 1);
574	      else if (e.name.startsWith('rollout-') && e.name.endsWith('.jsonl')) out.push(p);
575	    }
576	  };
577	  await walk(root, 0);
578	  return out;
579	}
580	
581	const UUID_RE = /([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})(?:\.jsonl)?$/;
582	
583	async function build() {
584	  const sessions = store.list();
585	  const byClaudeUuid = new Map(sessions.filter((s) => s.cli === 'claude' && s.sessionUuid).map((s) => [s.sessionUuid, s]));
586	  const byCodexId = new Map(sessions.filter((s) => s.codexSessionId).map((s) => [s.codexSessionId, s]));
587	
588	  const perSession = new Map(); // session id -> aggregate stats
589	  const digests = new Map();    // session id -> digest of the freshest file
590	  const other = emptyStats();
591	  const totals = emptyStats();
592	
593	  const attribute = (session, parsed) => {
594	    if (!parsed) return;
595	    const { stats, digest } = parsed;
596	    mergeInto(totals, stats);
597	    if (session) {
598	      if (!perSession.has(session.id)) perSession.set(session.id, emptyStats());
599	      mergeInto(perSession.get(session.id), stats);
600	      const prev = digests.get(session.id);
601	      if (!prev || stats.lastTs > prev._ts) digests.set(session.id, { ...digest, _ts: stats.lastTs });
602	    } else {
603	      mergeInto(other, stats);
604	    }
605	  };
606	
607	  const seenFiles = new Set(); // for fileCache eviction (rotated/deleted transcripts)
608	  for (const p of await claudeFiles()) {
609	    seenFiles.add(p);
610	    const m = path.basename(p).match(UUID_RE);
611	    attribute(m ? byClaudeUuid.get(m[1]) : null, await statsFor(p, parseClaude));
612	    await yieldLoop();
613	  }
614	  // Codex fallback: sessions created before capture-and-pin have no
615	  // codexSessionId — attribute their rollouts by cwd when it's unambiguous.
616	  const byCodexCwd = new Map();
617	  for (const s of sessions.filter((x) => x.cli === 'codex')) {
618	    const key = path.resolve(WORKSPACES_DIR, s.path ?? s.id);
619	    byCodexCwd.set(key, byCodexCwd.has(key) ? 'ambiguous' : s);
620	  }
621	  for (const p of await codexFiles()) {
622	    seenFiles.add(p);
623	    const parsed = await statsFor(p, parseCodex);
624	    await yieldLoop();
625	    if (!parsed) continue;
626	    if (parsed.stats.subagent) continue; // Codex guardian subagent — not the user's thread
627	    const m = path.basename(p).match(UUID_RE);
628	    let session = m ? byCodexId.get(m[1]) : null;
629	    if (!session && parsed.stats.cwd) {
630	      const hit = byCodexCwd.get(parsed.stats.cwd);
631	      if (hit && hit !== 'ambiguous') session = hit;
632	    }
633	    attribute(session, parsed);
634	  }
635	
636	  // OpenClaw: every pane shares the ONE embedded agent (agent "main"), so its
637	  // traces belong to the single OpenClaw session when unambiguous, else other.
638	  const ocSessions = sessions.filter((s) => s.cli === 'openclaw');
639	  const ocOwner = ocSessions.length === 1 ? ocSessions[0] : null;
640	  for (const p of await openclawFiles()) {
641	    seenFiles.add(p);
642	    // OpenClaw state lives on LOCAL disk now (see entrypoint.sh), so reads no
643	    // longer risk tripping its metadata fence like on FUSE — keep a small
644	    // quiet margin anyway since its session fence is unusually touchy.
645	    attribute(ocOwner, await statsFor(p, parseOpenClaw, 10_000));
646	    await yieldLoop();
647	  }
648	  // Evict cache entries for files that no longer exist (rotated Codex rollouts,
649	  // deleted transcripts) so fileCache doesn't grow unbounded on a long-lived Space.
650	  for (const k of fileCache.keys()) if (!seenFiles.has(k)) fileCache.delete(k);
651	
652	  // opencode: sessions attribute by their recorded directory (like codex cwd).
653	  const opencodeByDir = new Map();
654	  for (const s of sessions.filter((x) => x.cli === 'opencode')) {
655	    const key = path.resolve(WORKSPACES_DIR, s.path ?? s.id);
656	    opencodeByDir.set(key, opencodeByDir.has(key) ? 'ambiguous' : s);
657	  }
658	  for (const { directory, parsed } of readOpencode()) {
659	    const hit = directory ? opencodeByDir.get(path.resolve(directory)) : null;
660	    attribute(hit && hit !== 'ambiguous' ? hit : null, parsed);
661	  }
662	
663	  // Hermes: same story — sessions record their cwd.
664	  const hermesByDir = new Map();
665	  for (const s of sessions.filter((x) => x.cli === 'hermes')) {
666	    const key = path.resolve(WORKSPACES_DIR, s.path ?? s.id);
667	    hermesByDir.set(key, hermesByDir.has(key) ? 'ambiguous' : s);
668	  }
669	  for (const { directory, parsed } of readHermes()) {
670	    const hit = directory ? hermesByDir.get(path.resolve(directory)) : null;
671	    attribute(hit && hit !== 'ambiguous' ? hit : null, parsed);
672	  }
673	
674	  return { perSession, digests, other, totals, sessions };
675	}
676	
677	// Stale-while-revalidate: a build over a large transcript history can take
678	// longer than the poll interval. Serve the last result INSTANTLY and refresh
679	// in the background, and never run two builds at once — otherwise every poll
680	// kicked off a fresh overlapping build and pinned the event loop (the Overview
681	// lag). The first-ever call (no cached value) awaits the build once.
682	let building = null;
683	function memoized() {
684	  const fresh = resultMemo.val && Date.now() - resultMemo.ts < TTL;
685	  if (fresh) return resultMemo.val;
686	  if (!building) {
687	    building = build()
688	      .then((v) => { resultMemo = { ts: Date.now(), val: Promise.resolve(v) }; return v; })
689	      .catch(() => resultMemo.val || Promise.resolve({ perSession: new Map(), digests: new Map(), other: emptyStats(), totals: emptyStats(), sessions: store.list() }))
690	      .finally(() => { building = null; });
691	  }
692	  return resultMemo.val || building;
693	}
694	
695	export async function buildTraces() {
696	  const { perSession, totals, sessions } = await memoized();
697	  // Every agent session gets a row, traced or not; files that belong to no
698	  // live session (deleted panes, ambiguous attribution) only show in totals.
699	  return {
700	    sessions: sessions
701	      .filter((s) => s.cli !== 'shell' && s.cli !== 'files')
702	      .map((s) => ({ id: s.id, name: s.name, cli: s.cli, path: s.path, ...(perSession.get(s.id) || emptyStats()) }))
703	      .sort((a, b) => b.lastTs - a.lastTs),
704	    totals,
705	    generatedAt: new Date().toISOString(),
706	  };
707	}
708	
709	/** Per-session "since your last prompt" digests, keyed by session id. */
710	export async function traceDigests() {
711	  const { digests } = await memoized();
712	  return digests;
713	}
714	
715	/** Targeted digest for ONE session — parses only its own transcript files so
716	 *  the Overview can fill tiles progressively instead of waiting for the full
717	 *  build. Cheap for Claude (transcript filename == sessionUuid) and Codex (the
718	 *  pinned rollout); db-backed CLIs return null and ride the bulk pass. Parsed
719	 *  files land in the shared per-file cache, so nothing is read twice. */
720	export async function digestFor(s) {
721	  try {
722	    if (s.cli === 'claude' && s.sessionUuid) {
723	      let best = null;
724	      for (const p of await claudeFiles()) {
725	        if (!path.basename(p).includes(s.sessionUuid)) continue;
726	        const parsed = await statsFor(p, parseClaude);
727	        if (parsed && (!best || parsed.stats.lastTs > best.stats.lastTs)) best = parsed;
728	      }
729	      return best ? best.digest : null;
730	    }
731	    if (s.cli === 'codex' && s.codexRollout && fs.existsSync(s.codexRollout)) {
732	      const parsed = await statsFor(s.codexRollout, parseCodex);
733	      if (parsed && !parsed.stats.subagent) return parsed.digest;
734	    }
735	  } catch { /* fall through to the bulk pass */ }
736	  return null;
737	}
