435	export function copySelection(id) {
436	  if (!USE_TMUX) return null;
437	  const bufferName = `am-copy-${tmuxName(id)}`;
438	  let text = '';
439	  try {
440	    text = execFileSync('tmux', ['save-buffer', '-b', bufferName, '-'], { encoding: 'utf8', env: TERM_ENV });
