35	export function init() {
36	  load();
37	  let changed = false;
38	  for (const s of sessions) {
39	    if (!s.sessionUuid) { s.sessionUuid = crypto.randomUUID(); changed = true; }
40	  }
41	  if (changed) persist();
42	  // NOTE: `path` migration from the old folder/group-folder model happens in
43	  // index.js (it needs the groups store).
44	}
45	
46	export function list() {
47	  return sessions.slice();
48	}
49	
50	export function get(id) {
51	  return sessions.find((s) => s.id === id) || null;
52	}
53	
54	export function create({ name, cli, path }) {
